sksl:
uniform shader image;
uniform float2 size;
uniform float time;
uniform float highlights;
uniform float shadows;
uniform float style;
half4 main(float2 coord)
{
    half4 c = image.eval(coord);
    if (c.a <= 0.001) return half4(0.0);
    half3 col = c.rgb / c.a;
    half l = saturate(dot(col, half3(0.2126, 0.7152, 0.0722)));
    half hi = 1.89 * pow(l, 3.5) * (1.0 - l);
    half lo = 1.89 * pow(1.0 - l, 3.5) * l;
    half3 outc = clamp(col + (highlights - 1.0) * hi + (shadows - 1.0) * lo, 0.0, 1.0);
    if (style > 0.5) {
        float y = clamp(dot(float3(col), float3(0.2126, 0.7152, 0.0722)), 0.0, 1.0);
        float p = 1.0 / max(2.0 - min(highlights, 1.0), 0.001);
        float om = max(1.0 - y, 0.0);
        float dh = clamp((1.0 - (pow(om, p) - 0.78 * pow(om, 2.0 * p))) - y, -1.0, 0.0);
        float s = clamp(shadows, 0.0, 2.0);
        float ds = (s - 1.0) * 1.85 * pow(clamp(1.0 - y / 0.76, 0.0, 1.0), 2.6) * y;
        float o = y + dh + ds;
        float3 kept = y > 0.0001 ? clamp(float3(col) * max(o, 0.0) / y, 0.0, 1.0) : float3(0.0);
        float w = clamp(max(highlights - 1.0, 0.0) * 1.2 * pow(clamp((dot(kept, float3(0.2126, 0.7152, 0.0722)) - 0.3) / 0.55, 0.0, 1.0), 2.5), 0.0, 1.0);
        outc = half3(kept + (1.0 - kept) * w);
    }
    return half4(outc * c.a, c.a);
}
